//! Exports the forwarder table generated by `tools/kernelx_exports.py`
//! (`runtime/kernelx/kernelx_forwarders.inc`, one `/export:Name=dll.Name` line per function),
//! so this cdylib forwards the same 2,661 functions as the C++ kernelx.dll.
//!
//! rustc passes its own module-definition file to the linker, so forwarders given as linker
//! options are not honoured. As TomBox does (`crates/compat/advapi32/build.rs`, GPL-3.0-or-later),
//! the table becomes a `.def` file, MSVC's `lib.exe` turns it into an export file (`.exp`), and
//! that file is linked into the DLL.

use std::fmt::Write as _;
use std::path::PathBuf;
use std::process::Command;

const TABLE: &str = "../../runtime/kernelx/kernelx_forwarders.inc";
const PREFIX: &str = "#pragma comment(linker, \"/export:";
const TARGET: &str = "x86_64-pc-windows-msvc";

fn main() {
    println!("cargo:rerun-if-changed={TABLE}");
    let text = std::fs::read_to_string(TABLE)
        .unwrap_or_else(|e| panic!("{TABLE}: {e} (generated by tools/kernelx_exports.py)"));
    let mut def = String::from("LIBRARY kernelx\nEXPORTS\n");
    let mut count = 0;
    for line in text.lines().filter_map(|l| l.strip_prefix(PREFIX)) {
        let entry = line
            .strip_suffix("\")")
            .unwrap_or_else(|| panic!("{TABLE}: unexpected line {line}"));
        if !entry.contains('=') {
            panic!("{TABLE}: no forwarder in {entry}");
        }
        writeln!(def, "    {entry}").expect("writing to a String");
        count += 1;
    }
    assert!(count > 0, "{TABLE}: no forwarder found");
    println!("cargo:rustc-env=KERNELX_FORWARDERS={count}");
    if std::env::var("CARGO_CFG_TARGET_ENV").as_deref() != Ok("msvc") {
        return;
    }
    let out = PathBuf::from(std::env::var("OUT_DIR").expect("OUT_DIR set by cargo"));
    let (def_path, lib_path, exp_path) = (
        out.join("kernelx_exports.def"),
        out.join("kernelx_exports.lib"),
        out.join("kernelx_exports.exp"),
    );
    std::fs::write(&def_path, def).expect("writing kernelx_exports.def");
    let mut lib: Command = cc::windows_registry::find(TARGET, "lib.exe")
        .expect("lib.exe (MSVC librarian) not found: needed for the forwarder export table");
    let status = lib
        .arg("/NOLOGO")
        .arg("/MACHINE:X64")
        .arg(format!("/DEF:{}", def_path.display()))
        .arg(format!("/OUT:{}", lib_path.display()))
        .status()
        .expect("running lib.exe");
    assert!(
        status.success() && exp_path.exists(),
        "lib.exe did not produce {}",
        exp_path.display()
    );
    println!("cargo:rustc-cdylib-link-arg={}", exp_path.display());
}
